<?php
namespace App\Http\Controllers; use App\Models\Company; use App\Services\CompanyAccess; use Illuminate\Http\Request;
class CompanyController extends Controller {public function index(Request $r){return Company::whereIn('id',CompanyAccess::ids($r->user()))->orderBy('legal_name')->paginate(50);}public function store(Request $r){$d=$r->validate(['legal_name'=>'required|string|max:255','trade_name'=>'nullable|string|max:255','tax_id'=>'required|digits_between:11,14|unique:companies,tax_id','state_registration'=>'nullable|string|max:30']);$c=Company::create($d);$c->users()->attach($r->user()->id,['is_default'=>false]);return response()->json($c,201);}public function update(Request $r,Company $company){CompanyAccess::ensure($r->user(),$company->id);$d=$r->validate(['legal_name'=>'sometimes|string|max:255','trade_name'=>'nullable|string|max:255','state_registration'=>'nullable|string|max:30','active'=>'sometimes|boolean','settings'=>'sometimes|array']);$company->update($d);return $company;}public function destroy(Request $r,Company $company){CompanyAccess::ensure($r->user(),$company->id);$company->update(['active'=>false]);return response()->noContent();}}
